    [Tooltip("最少道具数")]
    public int minItems = 0;

    [Tooltip("最多道具数")]
    public int maxItems = 2;

    [Tooltip("品质权重覆盖（留空则使用 ItemsLibrary 默认权重）")]
    public QualityWeight[] qualityWeights;

